from pathlib import Path
import ast, json
from collections import defaultdict

src = Path('/inputs')
out = Path('/work/layout.json')
paths = sorted((p for p in src.iterdir()
                if p.is_file() and p.suffix == '.py'
                and p.name != '__init__.py'
                and not p.name.startswith('test_')
                and not p.name.endswith('_test.py')),
               key=lambda p: p.name)
by_stem = {p.stem: p.name for p in paths}
line_counts = {}
graph = {}

for p in paths:
    text = p.read_text(encoding='utf-8')
    line_counts[p.name] = len(text.splitlines())
    tree = ast.parse(text, filename=str(p))
    targets = set()
    for node in ast.walk(tree):
        candidates = []
        if isinstance(node, ast.Import):
            for alias in node.names:
                prefix = 'skillc.frontend.'
                if alias.name.startswith(prefix):
                    remainder = alias.name[len(prefix):]
                    if remainder:
                        candidates.append(remainder.split('.', 1)[0])
        elif isinstance(node, ast.ImportFrom):
            if node.level == 1:
                if node.module:
                    candidates.append(node.module.split('.', 1)[0])
                else:
                    candidates.extend(alias.name.split('.', 1)[0]
                                      for alias in node.names if alias.name != '*')
            elif node.level == 0:
                package = 'skillc.frontend'
                if node.module == package:
                    candidates.extend(alias.name.split('.', 1)[0]
                                      for alias in node.names if alias.name != '*')
                elif node.module and node.module.startswith(package + '.'):
                    candidates.append(node.module[len(package) + 1:].split('.', 1)[0])
        for stem in candidates:
            if stem in by_stem and by_stem[stem] != p.name:
                targets.add(by_stem[stem])
    graph[p.name] = targets

files = [
    {'name': p.name, 'lines': line_counts[p.name], 'imports': sorted(graph[p.name])}
    for p in paths
]

# Map every qualifying prefix to its member set, then collapse identical sets.
stems = sorted(by_stem)
sets_to_prefixes = defaultdict(list)
all_prefixes = {stem[:n] for stem in stems for n in range(4, len(stem) + 1)}
for prefix in all_prefixes:
    members = frozenset(stem for stem in stems if stem.startswith(prefix))
    if len(members) >= 3:
        sets_to_prefixes[members].append(prefix)

def common_prefix(strings):
    first, *rest = sorted(strings)
    last = rest[-1] if rest else first
    i = 0
    while i < min(len(first), len(last)) and first[i] == last[i]:
        i += 1
    return first[:i]

prefix_clusters = []
for member_stems in sets_to_prefixes:
    member_files = sorted(by_stem[s] for s in member_stems)
    prefix_clusters.append({
        'prefix': common_prefix(member_stems),
        'files': member_files,
        'lines': sum(line_counts[name] for name in member_files),
    })
prefix_clusters.sort(key=lambda row: row['prefix'])

import_tree_clusters = []
for root in sorted(graph):
    if len(graph[root]) < 3:
        continue
    reachable = set()
    stack = [root]
    while stack:
        name = stack.pop()
        if name in reachable:
            continue
        reachable.add(name)
        stack.extend(graph[name] - reachable)
    if len(reachable) >= 5:
        names = sorted(reachable)
        import_tree_clusters.append({
            'root': root,
            'files': names,
            'lines': sum(line_counts[name] for name in names),
        })
import_tree_clusters.sort(key=lambda row: row['root'])

payload = {
    'files': files,
    'prefix_clusters': prefix_clusters,
    'import_tree_clusters': import_tree_clusters,
}
out.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
